CREATE TABLE "health_scans" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "store_id" integer, "type" varchar not null, "status" varchar not null, "initiated_by" integer, "pages_total" integer not null default '0', "pages_checked" integer not null default '0', "products_checked" integer not null default '0', "images_checked" integer not null default '0', "assets_checked" integer not null default '0', "links_checked" integer not null default '0', "issues_found" integer not null default '0', "critical_count" integer not null default '0', "warning_count" integer not null default '0', "opportunity_count" integer not null default '0', "passed_count" integer not null default '0', "overall_score" integer, "category_scores" text, "progress" text, "comparison" text, "error" text, "current_step" varchar, "started_at" datetime, "completed_at" datetime, "created_at" datetime, "updated_at" datetime);
