CREATE TABLE "product_feature_values" ("id" integer primary key autoincrement not null, "product_id" integer not null, "feature_id" integer not null, "feature_value_id" integer not null, foreign key("product_id") references "products"("id") on delete cascade, foreign key("feature_id") references "features"("id") on delete cascade, foreign key("feature_value_id") references "feature_values"("id") on delete cascade);
CREATE TABLE "product_gift_card_amounts" ("id" integer primary key autoincrement not null, "product_id" integer not null, "value" numeric not null, "selling_price" numeric, "is_enabled" tinyint(1) not null default '1', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_gift_cards" ("id" integer primary key autoincrement not null, "product_id" integer not null, "amount_type" varchar not null default 'fixed', "min_amount" numeric, "max_amount" numeric, "default_amount" numeric, "amount_step" numeric, "delivery_method" varchar not null default 'email', "recipient_name_enabled" tinyint(1) not null default '1', "recipient_name_required" tinyint(1) not null default '0', "recipient_email_enabled" tinyint(1) not null default '1', "recipient_email_required" tinyint(1) not null default '1', "sender_name_enabled" tinyint(1) not null default '1', "sender_name_required" tinyint(1) not null default '0', "gift_message_enabled" tinyint(1) not null default '1', "gift_message_required" tinyint(1) not null default '0', "validity_type" varchar not null default 'never', "validity_days" integer, "expiry_date" date, "allow_online_redemption" tinyint(1) not null default '1', "allow_offline_redemption" tinyint(1) not null default '0', "usage_type" varchar not null default 'multiple', "allow_partial_redemption" tinyint(1) not null default '1', "code_length" integer not null default '12', "code_prefix" varchar, "code_charset" varchar not null default 'alphanumeric', "code_uppercase" tinyint(1) not null default '1', "min_order_amount" numeric, "max_order_amount" numeric, "restrictions" text, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_images" ("id" integer primary key autoincrement not null, "product_id" integer not null, "path" varchar not null, "alt" varchar, "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_preorders" ("id" integer primary key autoincrement not null, "product_id" integer not null, "start_at" datetime, "end_at" datetime, "release_at" datetime, "fulfillment_at" datetime, "expected_delivery_at" datetime, "payment_type" varchar not null default 'full', "deposit_type" varchar, "deposit_value" numeric, "min_quantity" integer not null default '1', "max_quantity" integer, "total_limit" integer, "orders_placed" integer not null default '0', "message" text, "show_badge" tinyint(1) not null default '1', "show_release_date" tinyint(1) not null default '1', "show_delivery_date" tinyint(1) not null default '0', "show_countdown_pdp" tinyint(1) not null default '0', "show_countdown_listing" tinyint(1) not null default '0', "show_image_label" tinyint(1) not null default '0', "notify_me_enabled" tinyint(1) not null default '0', "fulfillment_rule" varchar not null default 'auto', "preorder_price" numeric, "preorder_price_valid_until" datetime, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_qty_prices" ("id" integer primary key autoincrement not null, "product_id" integer not null, "min_qty" numeric not null default ('1'), "max_qty" numeric, "price" numeric not null, "position" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, foreign key("product_id") references products("id") on delete cascade on update no action);
CREATE TABLE "product_questions" ("id" integer primary key autoincrement not null, "product_id" integer not null, "customer_id" integer not null, "body" text not null, "status" varchar not null default 'pending', "is_approved" tinyint(1) not null default '0', "rejected_reason" varchar, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE "product_relations" ("id" integer primary key autoincrement not null, "product_id" integer not null, "related_product_id" integer not null, "type" varchar not null, foreign key("product_id") references "products"("id") on delete cascade, foreign key("related_product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_rental_assets" ("id" integer primary key autoincrement not null, "product_id" integer not null, "asset_id" varchar not null, "serial_number" varchar, "barcode" varchar, "status" varchar not null default 'available', "location" varchar, "condition" varchar, "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_rental_pricing_tiers" ("id" integer primary key autoincrement not null, "product_id" integer not null, "min_duration" integer not null, "max_duration" integer not null, "unit" varchar not null, "price" numeric not null, "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_rentals" ("id" integer primary key autoincrement not null, "product_id" integer not null, "rental_unit" varchar not null default 'day', "min_duration" integer not null default '1', "max_duration" integer not null default '30', "default_duration" integer not null default '1', "pricing_model" varchar not null default 'per_day', "availability_config" text, "security_deposit_type" varchar not null default 'none', "security_deposit_value" numeric, "inventory_mode" varchar not null default 'quantity', "maintenance_units" integer not null default '0', "out_of_service_units" integer not null default '0', "fulfillment_method" varchar not null default 'both', "return_method" varchar not null default 'both', "return_location" varchar, "grace_period" integer, "grace_period_unit" varchar, "late_fee_type" varchar not null default 'none', "late_fee_value" numeric, "damage_fee_type" varchar not null default 'none', "damage_fee_value" numeric, "lost_item_fee_type" varchar not null default 'none', "lost_item_fee_value" numeric, "cleaning_fee" numeric, "policies" text, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_services" ("id" integer primary key autoincrement not null, "product_id" integer not null, "service_type" varchar not null default 'one_time', "duration" numeric, "duration_unit" varchar, "pricing_model" varchar not null default 'fixed', "delivery_method" varchar not null default 'online', "meeting_instructions" text, "delivery_instructions" text, "online_service_url" varchar, "service_area" varchar, "location_info" text, "travel_fee" numeric, "availability_config" text, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_shipping_method" ("product_id" integer not null, "shipping_method_id" integer not null, foreign key("product_id") references "products"("id") on delete cascade, foreign key("shipping_method_id") references "shipping_methods"("id") on delete cascade, primary key ("product_id", "shipping_method_id"));
CREATE TABLE "product_store" ("id" integer primary key autoincrement not null, "product_id" integer not null, "store_id" integer not null, "is_visible" tinyint(1) not null default '1', "price" numeric, "url_key" varchar, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("store_id") references "stores"("id") on delete cascade);
CREATE TABLE "product_subscription_plans" ("id" integer primary key autoincrement not null, "product_id" integer not null, "subscription_plan_id" integer not null, "price" numeric not null default '0', "discount_type" varchar, "discount_value" numeric, "is_enabled" tinyint(1) not null default '1', "is_default" tinyint(1) not null default '0', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("subscription_plan_id") references "subscription_plans"("id") on delete restrict);
CREATE TABLE "product_supplier" ("product_id" integer not null, "supplier_id" integer not null, "supplier_reference" varchar, "wholesale_price" numeric, "is_default" tinyint(1) not null default '0', foreign key("product_id") references "products"("id") on delete cascade, foreign key("supplier_id") references "suppliers"("id") on delete cascade, primary key ("product_id", "supplier_id"));
CREATE TABLE "product_tag" ("product_id" integer not null, "tag_id" integer not null, foreign key("product_id") references "products"("id") on delete cascade, foreign key("tag_id") references "tags"("id") on delete cascade, primary key ("product_id", "tag_id"));
CREATE TABLE "product_translations" ("id" integer primary key autoincrement not null, "product_id" integer not null, "language_code" varchar not null, "name" varchar not null, "slug" varchar not null, "short_description" text, "description" text, "meta_title" varchar, "meta_description" varchar, "meta_keywords" varchar, "focus_keyword" varchar, "canonical_url" varchar, "robots" varchar not null default 'index,follow', "og_title" varchar, "og_description" text, "subscription_message" text, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_variant_values" ("product_variant_id" integer not null, "attribute_value_id" integer not null, foreign key("product_variant_id") references "product_variants"("id") on delete cascade, foreign key("attribute_value_id") references "attribute_values"("id") on delete cascade, primary key ("product_variant_id", "attribute_value_id"));
CREATE TABLE "product_variants" ("id" integer primary key autoincrement not null, "product_id" integer not null, "sku" varchar, "barcode" varchar, "price" numeric, "sale_price" numeric, "sale_price_type" varchar not null default ('fixed'), "cost_price" numeric, "stock_qty" numeric not null default '0', "manage_stock" tinyint(1) not null default ('1'), "stock_status" varchar not null default ('in_stock'), "allow_backorder" tinyint(1) not null default ('0'), "weight" numeric, "length" numeric, "width" numeric, "height" numeric, "cover_path" varchar, "is_enabled" tinyint(1) not null default ('1'), "is_default" tinyint(1) not null default ('0'), "position" integer not null default ('0'), "combination_key" varchar not null, "created_at" datetime, "updated_at" datetime, "cover_image_id" integer, "reserved_qty" numeric not null default '0', foreign key("cover_image_id") references product_images("id") on delete set null on update no action, foreign key("product_id") references products("id") on delete cascade on update no action);
CREATE TABLE "products" ("id" integer primary key autoincrement not null, "type" varchar not null default ('simple'), "sku" varchar not null, "seller_id" integer, "brand_id" integer, "tax_class_id" integer, "default_category_id" integer, "price" numeric not null default ('0'), "compare_price" numeric, "sale_price" numeric, "sale_price_type" varchar not null default ('fixed'), "sale_starts_at" date, "sale_ends_at" date, "cost_price" numeric, "stock_qty" numeric not null default ('0'), "reserved_qty" numeric not null default ('0'), "stock_status" varchar not null default ('in_stock'), "low_stock_threshold" integer not null default ('5'), "low_stock_alert" integer not null default ('10'), "critical_stock" integer not null default ('3'), "manage_stock" tinyint(1) not null default ('1'), "allow_backorder" tinyint(1) not null default ('0'), "backorder_status" varchar not null default ('deny'), "notify_low_stock" tinyint(1) not null default ('1'), "notify_out_of_stock" tinyint(1) not null default ('1'), "min_qty" numeric, "max_qty" numeric, "qty_step" numeric, "weight" numeric, "weight_class" varchar not null default ('kg'), "length" numeric, "width" numeric, "height" numeric, "length_class" varchar not null default ('cm'), "processing_time" integer, "processing_time_unit" varchar not null default ('days'), "delivery_from" integer, "delivery_to" integer, "additional_shipping_cost" numeric not null default ('0'), "available_all_carriers" tinyint(1) not null default ('1'), "barcode" varchar, "isbn" varchar, "upc" varchar, "mpn" varchar, "gtin" varchar, "display_condition" tinyint(1) not null default ('0'), "condition" varchar, "visibility" varchar not null default ('both'), "available_for_order" tinyint(1) not null default ('1'), "show_price" tinyint(1) not null default ('1'), "is_enabled" tinyint(1) not null default ('1'), "is_new" tinyint(1) not null default ('0'), "is_on_sale" tinyint(1) not null default ('0'), "is_best_seller" tinyint(1) not null default ('0'), "cover_path" varchar, "created_at" datetime, "updated_at" datetime, "supplier_id" integer, "customization_enabled" tinyint(1) not null default ('0'), "subscription_enabled" tinyint(1) not null default ('0'), "purchase_option" varchar not null default ('one_time'), "selection_mode" varchar, "bundle_type" varchar, "pricing_mode" varchar, "pricing_discount_type" varchar, "pricing_discount_value" numeric, "inventory_mode" varchar, "shipping_mode" varchar, "preorder_enabled" tinyint(1) not null default ('0'), "video_url" varchar, "sale_unit" varchar not null default ('piece'), "sale_unit_code" varchar not null default ('pc'), "low_stock_notified_at" datetime, foreign key("seller_id") references sellers("id") on delete set null on update no action, foreign key("default_category_id") references categories("id") on delete set null on update no action, foreign key("tax_class_id") references tax_classes("id") on delete set null on update no action, foreign key("brand_id") references brands("id") on delete set null on update no action, foreign key("supplier_id") references suppliers("id") on delete set null on update no action);
CREATE TABLE "profile_permission" ("profile_id" integer not null, "permission_id" integer not null, foreign key("profile_id") references "profiles"("id") on delete cascade, foreign key("permission_id") references "permissions"("id") on delete cascade, primary key ("profile_id", "permission_id"));
CREATE TABLE "profile_role" ("profile_id" integer not null, "role_id" integer not null, foreign key("profile_id") references "profiles"("id") on delete cascade, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("profile_id", "role_id"));
CREATE TABLE "profiles" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text, "is_enabled" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "purchase_order_items" ("id" integer primary key autoincrement not null, "purchase_order_id" integer not null, "product_id" integer, "sku" varchar, "name" varchar, "qty_ordered" numeric not null default '0', "qty_received" numeric not null default '0', "unit_cost" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("purchase_order_id") references "purchase_orders"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete set null);
CREATE TABLE "purchase_order_receipts" ("id" integer primary key autoincrement not null, "purchase_order_id" integer not null, "purchase_order_item_id" integer not null, "product_id" integer, "warehouse_id" integer, "admin_id" integer, "qty" numeric not null, "unit_cost" numeric not null default '0', "inventory_reference" varchar, "is_final" tinyint(1) not null default '0', "reversed_at" datetime, "reversed_by_admin_id" integer, "reversal_reference" varchar, "notes" varchar, "created_at" datetime, "updated_at" datetime, foreign key("purchase_order_id") references "purchase_orders"("id") on delete cascade, foreign key("purchase_order_item_id") references "purchase_order_items"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete set null, foreign key("warehouse_id") references "warehouses"("id") on delete set null, foreign key("admin_id") references "admins"("id") on delete set null);
CREATE TABLE "purchase_orders" ("id" integer primary key autoincrement not null, "number" varchar not null, "supplier_id" integer, "warehouse_id" integer, "status" varchar not null default 'draft', "expected_at" date, "notes" text, "ordered_at" datetime, "received_at" datetime, "created_at" datetime, "updated_at" datetime, "discount_type" varchar, "discount_value" numeric not null default '0', "shipping_cost" numeric not null default '0', foreign key("supplier_id") references "suppliers"("id") on delete set null, foreign key("warehouse_id") references "warehouses"("id") on delete set null);
CREATE TABLE "return_custom_fields" ("id" integer primary key autoincrement not null, "code" varchar not null, "label" varchar not null, "type" varchar not null default 'text', "is_required" tinyint(1) not null default '0', "position" integer not null default '0', "input_validation" varchar, "is_enabled" tinyint(1) not null default '1', "options" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "return_messages" ("id" integer primary key autoincrement not null, "order_return_id" integer not null, "admin_id" integer, "customer_id" integer, "body" text not null, "is_admin" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "return_reasons" ("id" integer primary key autoincrement not null, "code" varchar not null, "name" varchar not null, "is_enabled" tinyint(1) not null default '1', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "return_rules" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "return_period" integer not null default '30', "is_enabled" tinyint(1) not null default '1', "is_default" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "return_statuses" ("id" integer primary key autoincrement not null, "title" varchar not null, "color" varchar not null default '#6B7280', "is_enabled" tinyint(1) not null default '1', "is_default" tinyint(1) not null default '0', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "review_votes" ("id" integer primary key autoincrement not null, "review_id" integer not null, "customer_id" integer not null, "helpful" tinyint(1) not null, "created_at" datetime, "updated_at" datetime, foreign key("review_id") references "reviews"("id") on delete cascade, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE "reviews" ("id" integer primary key autoincrement not null, "product_id" integer not null, "customer_id" integer, "guest_name" varchar, "guest_email" varchar, "rating" integer not null, "title" varchar, "body" text, "is_approved" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, "status" varchar not null default 'pending', "rejected_reason" varchar, "admin_reply" text, "admin_replied_at" datetime, "is_verified_purchase" tinyint(1) not null default '0', "photo_path" varchar, "images" text, "video_path" varchar, "helpful_count" integer not null default '0', "not_helpful_count" integer not null default '0', foreign key("product_id") references "products"("id") on delete cascade, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE "roles" ("id" integer primary key autoincrement not null, "slug" varchar not null, "name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "saved_payment_methods" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "driver" varchar not null, "reference" varchar not null, "gateway_customer_ref" varchar, "brand" varchar, "last4" varchar, "exp_month" integer, "exp_year" integer, "is_default" tinyint(1) not null default '0', "revoked_at" datetime, "pending_action_url" varchar, "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE "saved_queries" ("id" integer primary key autoincrement not null, "store_id" integer, "admin_id" integer, "name" varchar not null, "sql" text not null, "last_run_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "search_pins" ("id" integer primary key autoincrement not null, "query" varchar not null, "product_id" integer not null, "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "search_redirects" ("id" integer primary key autoincrement not null, "query" varchar not null, "target_path" varchar not null, "is_enabled" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "search_synonyms" ("id" integer primary key autoincrement not null, "term" varchar not null, "aliases" varchar not null, "is_enabled" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "security_audit_logs" ("id" integer primary key autoincrement not null, "store_id" integer, "action" varchar not null, "actor_type" varchar not null default 'system', "actor_id" integer, "actor_email" varchar, "ip_address" varchar, "user_agent" varchar, "entity_type" varchar, "entity_id" integer, "payload" text, "created_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "seller_attributes" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "attribute_id" integer, "name" varchar not null, "code" varchar, "type" varchar not null default 'select', "supports_swatches" tinyint(1) not null default '0', "is_enabled" tinyint(1) not null default '1', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_brands" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "brand_id" integer, "name" varchar not null, "slug" varchar not null, "code" varchar, "description" text, "is_enabled" tinyint(1) not null default '1', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_categories" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "category_id" integer, "parent_id" integer, "name" varchar not null, "slug" varchar not null, "description" text, "is_enabled" tinyint(1) not null default '1', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_commissions" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "name" varchar not null default 'Default', "rate" numeric not null default '10', "is_default" tinyint(1) not null default '1', "is_enabled" tinyint(1) not null default '1', "notes" text, "created_at" datetime, "updated_at" datetime, "type" varchar not null default 'percent', foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_discounts" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "discount_rule_id" integer, "name" varchar not null, "code" varchar, "apply_as" varchar not null default 'coupon', "action" varchar not null default 'percent', "value" numeric not null default '0', "min_cart" numeric, "max_uses" integer, "used_count" integer not null default '0', "starts_at" datetime, "expires_at" datetime, "is_enabled" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_earnings" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "seller_order_id" integer, "order_id" integer, "product_id" integer, "gross_amount" numeric not null default '0', "commission_amount" numeric not null default '0', "net_amount" numeric not null default '0', "status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime, "order_item_id" integer, "commission_rate" numeric, "commission_type" varchar, "commission_value" numeric, "commission_source" varchar, "commission_rule_id" integer, "available_at" datetime, "released_at" datetime, "refunded_gross" numeric not null default '0', "refunded_commission" numeric not null default '0', "refunded_net" numeric not null default '0', "paid_net" numeric not null default '0', foreign key("seller_id") references "sellers"("id") on delete restrict, foreign key("seller_order_id") references "seller_orders"("id") on delete set null);
CREATE TABLE "seller_features" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "feature_id" integer, "name" varchar not null, "code" varchar, "type" varchar not null default 'select', "is_filterable" tinyint(1) not null default '1', "is_enabled" tinyint(1) not null default '1', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_ledger_entries" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "seller_order_id" integer, "order_id" integer, "seller_earning_id" integer, "entry_type" varchar not null, "direction" varchar not null, "amount" numeric not null, "currency_code" varchar not null default 'USD', "reference" varchar not null, "description" varchar, "meta" text, "created_at" datetime, "updated_at" datetime, "seller_withdrawal_id" integer, foreign key("seller_id") references "sellers"("id") on delete restrict, foreign key("seller_order_id") references "seller_orders"("id") on delete set null);
CREATE TABLE "seller_messages" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "customer_id" integer, "name" varchar not null, "email" varchar not null, "body" text not null, "reply_body" text, "replied_at" datetime, "is_read" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_order_items" ("id" integer primary key autoincrement not null, "seller_order_id" integer not null, "order_item_id" integer, "product_id" integer, "sku" varchar, "name" varchar not null, "qty" numeric not null default ('1'), "unit_price" numeric not null default ('0'), "tax_amount" numeric not null default ('0'), "total" numeric not null default ('0'), "created_at" datetime, "updated_at" datetime, "returned_qty" numeric not null default ('0'), "cancelled_qty" numeric not null default '0', foreign key("product_id") references products("id") on delete set null on update no action, foreign key("seller_order_id") references seller_orders("id") on delete cascade on update no action, foreign key("order_item_id") references order_items("id") on delete set null on update no action);
CREATE TABLE "seller_orders" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "order_id" integer not null, "number" varchar not null, "customer_email" varchar, "status" varchar not null default 'pending', "payment_status" varchar, "currency_code" varchar not null default 'USD', "subtotal" numeric not null default '0', "tax_total" numeric not null default '0', "shipping_total" numeric not null default '0', "discount_total" numeric not null default '0', "commission_total" numeric not null default '0', "earning_total" numeric not null default '0', "grand_total" numeric not null default '0', "billing_address" text, "shipping_address" text, "created_at" datetime, "updated_at" datetime, "commission_rate" numeric, "commission_source" varchar, "commission_type" varchar, "commission_value" numeric, "commission_rule_id" integer, "shipping_method_id" integer, foreign key("seller_id") references "sellers"("id") on delete restrict, foreign key("order_id") references "orders"("id") on delete restrict);
CREATE TABLE "seller_payment_methods" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "payment_method_id" integer, "type" varchar not null default 'bank', "name" varchar not null, "account_name" varchar, "account_number" varchar, "bank_name" varchar, "routing_number" varchar, "paypal_email" varchar, "notes" text, "is_default" tinyint(1) not null default '0', "is_enabled" tinyint(1) not null default '1', "config" text, "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_products" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "product_id" integer not null, "sku" varchar not null, "name" varchar not null, "slug" varchar, "description" text, "short_description" text, "price" numeric not null default ('0'), "compare_price" numeric, "stock_qty" integer not null default ('0'), "category_id" integer, "is_enabled" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, "approval_status" varchar not null default ('approved'), "approval_note" text, "reviewed_by" integer, "reviewed_at" datetime, foreign key("product_id") references products("id") on delete cascade on update no action, foreign key("seller_id") references sellers("id") on delete cascade on update no action, foreign key("reviewed_by") references "admins"("id") on delete set null);
CREATE TABLE "seller_return_items" ("id" integer primary key autoincrement not null, "seller_return_id" integer not null, "seller_order_item_id" integer not null, "order_item_id" integer, "product_id" integer, "qty" integer not null, "unit_price" numeric not null default '0', "line_total" numeric not null default '0', "tax_amount" numeric not null default '0', "gross_amount" numeric not null default '0', "commission_amount" numeric not null default '0', "net_amount" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("seller_return_id") references "seller_returns"("id") on delete cascade, foreign key("seller_order_item_id") references "seller_order_items"("id") on delete restrict);
CREATE TABLE "seller_returns" ("id" integer primary key autoincrement not null, "order_id" integer not null, "seller_order_id" integer not null, "seller_id" integer not null, "customer_id" integer, "number" varchar not null, "status" varchar not null default 'requested', "reason" varchar, "customer_note" text, "seller_note" text, "admin_note" text, "refund_subtotal" numeric not null default '0', "refund_tax" numeric not null default '0', "refund_total" numeric not null default '0', "commission_reversed" numeric not null default '0', "seller_net_reversed" numeric not null default '0', "restock" tinyint(1) not null default '1', "requested_at" datetime, "approved_at" datetime, "rejected_at" datetime, "received_at" datetime, "refunded_at" datetime, "approved_by_admin_id" integer, "rejected_by_admin_id" integer, "refunded_by_admin_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade, foreign key("seller_order_id") references "seller_orders"("id") on delete cascade, foreign key("seller_id") references "sellers"("id") on delete restrict);
CREATE TABLE "seller_revenues" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "period_date" date not null, "period_type" varchar not null default 'day', "order_count" integer not null default '0', "item_count" integer not null default '0', "gross_total" numeric not null default '0', "commission_total" numeric not null default '0', "net_total" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_reviews" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "customer_id" integer, "order_id" integer, "rating" integer not null default '5', "title" varchar, "body" text, "status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime, "seller_order_id" integer, "is_verified_purchase" tinyint(1) not null default '1', "moderated_by" integer, "moderated_at" datetime, "moderation_note" varchar, foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_shipping_methods" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "shipping_method_id" integer, "code" varchar not null, "name" varchar not null, "description" varchar, "type" varchar not null default 'flat', "price" numeric not null default '0', "is_enabled" tinyint(1) not null default '1', "config" text, "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_suppliers" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "supplier_id" integer, "name" varchar not null, "slug" varchar not null, "email" varchar, "phone" varchar, "city" varchar, "country" varchar, "description" text, "is_enabled" tinyint(1) not null default '1', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_translations" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "language_code" varchar not null, "shop_name" varchar not null, "description" text, "store_policy" text, "shipping_policy" text, "return_policy" text, "vacation_message" text, foreign key("seller_id") references "sellers"("id") on delete cascade);
CREATE TABLE "seller_withdrawals" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "seller_payment_method_id" integer, "amount" numeric not null default '0', "status" varchar not null default 'pending', "note" text, "processed_by" integer, "processed_at" datetime, "created_at" datetime, "updated_at" datetime, "payout_reference" varchar, "payout_rail" varchar, foreign key("seller_id") references "sellers"("id") on delete restrict);
CREATE TABLE "sellers" ("id" integer primary key autoincrement not null, "store_id" integer, "customer_id" integer not null, "status" varchar not null default ('pending'), "first_name" varchar not null, "last_name" varchar not null, "shop_name" varchar not null, "shop_slug" varchar not null, "profile_name" varchar not null, "email" varchar not null, "phone" varchar not null, "contact_name" varchar not null, "contact_phone" varchar not null, "contact_email" varchar, "address_line1" varchar not null, "address_line2" varchar, "city" varchar not null, "state" varchar, "postal_code" varchar not null, "country_code" varchar not null, "description" text, "tax_id" varchar, "logo_path" varchar, "commission_rate" numeric, "review_note" text, "reviewed_by" integer, "reviewed_at" datetime, "blocked_at" datetime, "created_at" datetime, "updated_at" datetime, "facebook_url" varchar, "twitter_url" varchar, "instagram_url" varchar, "youtube_url" varchar, "banner_path" varchar, "is_active" tinyint(1) not null default ('1'), "vacation_enabled" tinyint(1) not null default ('0'), "vacation_message" text, "store_policy" text, "shipping_policy" text, "return_policy" text, "payout_bank_account" varchar, "payout_bank_ifsc" varchar, "payout_upi_id" varchar, "payout_paypal_email" varchar, "health_score" integer, "health_band" varchar, "health_cancellation_rate" numeric, "health_avg_rating" numeric, "health_flag_count" integer, "health_refreshed_at" datetime, foreign key("reviewed_by") references admins("id") on delete set null on update no action, foreign key("customer_id") references customers("id") on delete cascade on update no action);
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "wento_platform_meta" ("id" integer primary key autoincrement not null, "platform_version" varchar not null default '1.0.0', "schema_version" varchar not null default '1.0.0', "upgraded_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "wento_upgrade_log" ("id" integer primary key autoincrement not null, "version" varchar not null, "status" varchar not null default 'applied', "message" text, "applied_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE INDEX IF NOT EXISTS "wento_upgrade_log_version_status_index" on "wento_upgrade_log" ("version", "status");

CREATE TABLE "shipment_items" ("id" integer primary key autoincrement not null, "shipment_id" integer not null, "order_item_id" integer, "seller_order_item_id" integer, "qty" integer not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("shipment_id") references "shipments"("id") on delete cascade);
CREATE TABLE "shipments" ("id" integer primary key autoincrement not null, "order_id" integer not null, "seller_order_id" integer, "seller_id" integer, "status" varchar not null default 'processing', "carrier" varchar, "tracking_number" varchar, "tracking_url" varchar, "shipped_at" datetime, "delivered_at" datetime, "shipping_address" text, "notes" text, "created_at" datetime, "updated_at" datetime, "shipping_method_id" integer, "shipping_cost" numeric not null default '0', foreign key("order_id") references "orders"("id") on delete cascade, foreign key("seller_order_id") references "seller_orders"("id") on delete cascade);
CREATE TABLE "shipping_method_store" ("id" integer primary key autoincrement not null, "shipping_method_id" integer not null, "store_id" integer not null, "is_enabled" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("shipping_method_id") references "shipping_methods"("id") on delete cascade, foreign key("store_id") references "stores"("id") on delete cascade);
CREATE TABLE "shipping_methods" ("id" integer primary key autoincrement not null, "code" varchar not null, "name" varchar not null, "driver" varchar not null default 'offline', "price" numeric not null default '0', "is_enabled" tinyint(1) not null default '1', "position" integer not null default '0', "config" text, "created_at" datetime, "updated_at" datetime, "description" text, "type" varchar not null default 'flat', "conditions" text, "rate_config" text, "seller_id" integer, "tax_class_id" integer, foreign key("tax_class_id") references "tax_classes"("id") on delete set null on update no action);
CREATE TABLE "shipping_zone_countries" ("id" integer primary key autoincrement not null, "shipping_zone_id" integer not null, "country_id" integer not null, foreign key("shipping_zone_id") references "shipping_zones"("id") on delete cascade);
CREATE TABLE "shipping_zones" ("id" integer primary key autoincrement not null, "name" varchar not null, "is_enabled" tinyint(1) not null default '1', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "shop_urls" ("id" integer primary key autoincrement not null, "scheme" varchar not null default ('http'), "domain" varchar not null, "port" integer, "physical_uri" varchar not null default ('/'), "virtual_uri" varchar not null default (''), "is_primary" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, "store_id" integer, foreign key("store_id") references "stores"("id") on delete cascade);
CREATE TABLE "sms_logs" ("id" integer primary key autoincrement not null, "to_phone" varchar not null, "body" varchar not null, "status" varchar not null default 'logged', "purpose" varchar, "error" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "customer_stock_alerts" ("id" integer primary key autoincrement not null, "product_id" integer not null, "customer_id" integer, "product_variant_id" integer not null default '0', "email" varchar not null, "first_name" varchar, "last_name" varchar, "notified_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE "preorder_notify_subscriptions" ("id" integer primary key autoincrement not null, "product_id" integer not null, "customer_id" integer not null, "notified_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE "stock_alerts" ("id" integer primary key autoincrement not null, "product_id" integer not null, "email" varchar not null, "notified_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "store_groups" ("id" integer primary key autoincrement not null, "name" varchar not null, "code" varchar not null, "description" text, "share_customers" tinyint(1) not null default '0', "share_orders" tinyint(1) not null default '0', "share_stock" tinyint(1) not null default '0', "color" varchar, "is_enabled" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "store_sharing_policies" ("id" integer primary key autoincrement not null, "store_id" integer not null, "family" varchar not null, "mode" varchar not null default 'own', "source_store_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("store_id") references "stores"("id") on delete cascade, foreign key("source_store_id") references "stores"("id") on delete set null);
CREATE TABLE "stores" ("id" integer primary key autoincrement not null, "store_group_id" integer not null, "name" varchar not null, "code" varchar not null, "email" varchar, "address" varchar, "theme" varchar not null default 'default', "is_default" tinyint(1) not null default '0', "is_enabled" tinyint(1) not null default '1', "color" varchar, "created_at" datetime, "updated_at" datetime, "theme_settings" text, foreign key("store_group_id") references "store_groups"("id") on delete cascade);
CREATE TABLE "storefront_api_keys" ("id" integer primary key autoincrement not null, "store_id" integer, "name" varchar not null, "key_prefix" varchar not null, "key_hash" varchar not null, "rate_limit" integer, "is_enabled" tinyint(1) not null default '1', "last_used_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("store_id") references "stores"("id") on delete set null);
CREATE UNIQUE INDEX "storefront_api_keys_key_hash_unique" on "storefront_api_keys" ("key_hash");
CREATE TABLE "subscription_plan_translations" ("id" integer primary key autoincrement not null, "subscription_plan_id" integer not null, "language_code" varchar not null, "name" varchar not null, foreign key("subscription_plan_id") references "subscription_plans"("id") on delete cascade);
CREATE TABLE "subscription_plans" ("id" integer primary key autoincrement not null, "is_enabled" tinyint(1) not null default '1', "position" integer not null default '0', "trial_enabled" tinyint(1) not null default '0', "trial_duration" integer not null default '0', "trial_cycle" integer not null default '1', "trial_frequency" varchar not null default 'month', "duration" integer not null default '0', "cycle" integer not null default '1', "frequency" varchar not null default 'month', "created_at" datetime, "updated_at" datetime, "deleted_at" datetime);
CREATE TABLE "supplier_translations" ("id" integer primary key autoincrement not null, "supplier_id" integer not null, "language_code" varchar not null, "name" varchar not null, "slug" varchar not null, "description" text, "meta_title" varchar, "meta_description" varchar, "meta_keywords" varchar, foreign key("supplier_id") references "suppliers"("id") on delete cascade);
CREATE TABLE "suppliers" ("id" integer primary key autoincrement not null, "email" varchar, "phone" varchar, "website" varchar, "address" varchar, "city" varchar, "postcode" varchar, "country" varchar, "logo_path" varchar, "is_enabled" tinyint(1) not null default '1', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, "seller_id" integer, "address_line2" varchar, "state" varchar, "facebook_url" varchar, "instagram_url" varchar, "youtube_url" varchar, "twitter_url" varchar, "linkedin_url" varchar, "tiktok_url" varchar);
CREATE TABLE "support_ticket_replies" ("id" integer primary key autoincrement not null, "support_ticket_id" integer not null, "admin_id" integer, "author" varchar not null default 'staff', "body" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "support_tickets" ("id" integer primary key autoincrement not null, "store_id" integer, "customer_id" integer, "name" varchar not null, "email" varchar not null, "order_number" varchar, "body" text not null, "status" varchar not null default 'open', "replied_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "tag_translations" ("id" integer primary key autoincrement not null, "tag_id" integer not null, "language_code" varchar not null, "name" varchar not null, "slug" varchar not null, foreign key("tag_id") references "tags"("id") on delete cascade);
CREATE TABLE "tags" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "tax_classes" ("id" integer primary key autoincrement not null, "name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "tax_rates" ("id" integer primary key autoincrement not null, "name" varchar not null, "rate" numeric not null default '0', "is_enabled" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "tax_rules" ("id" integer primary key autoincrement not null, "tax_class_id" integer not null, "country_id" integer, "name" varchar not null, "rate" numeric not null default ('0'), "is_enabled" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, "tax_zone_id" integer, "tax_rate_id" integer, "priority" integer not null default '0', "is_compound" tinyint(1) not null default '0', foreign key("country_id") references countries("id") on delete set null on update no action, foreign key("tax_class_id") references tax_classes("id") on delete cascade on update no action, foreign key("tax_zone_id") references "tax_zones"("id") on delete set null, foreign key("tax_rate_id") references "tax_rates"("id") on delete set null);
CREATE TABLE "tax_zone_regions" ("id" integer primary key autoincrement not null, "tax_zone_id" integer not null, "country_region_id" integer not null, foreign key("tax_zone_id") references "tax_zones"("id") on delete cascade, foreign key("country_region_id") references "country_regions"("id") on delete cascade);
CREATE TABLE "tax_zones" ("id" integer primary key autoincrement not null, "name" varchar not null, "country_id" integer, "is_enabled" tinyint(1) not null default '1', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("country_id") references "countries"("id") on delete set null);
CREATE TABLE "teams" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "color" varchar not null default ('primary'), "description" text, "is_enabled" tinyint(1) not null default ('1'), "default_profile_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("default_profile_id") references "profiles"("id") on delete set null);
CREATE TABLE "ui_string_translations" ("id" integer primary key autoincrement not null, "ui_string_id" integer not null, "language_code" varchar not null, "text" text not null, "created_at" datetime, "updated_at" datetime, foreign key("ui_string_id") references "ui_strings"("id") on delete cascade);
CREATE TABLE "ui_strings" ("id" integer primary key autoincrement not null, "surface" varchar not null, "page" varchar not null, "key" varchar not null, "source" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "url_redirects" ("id" integer primary key autoincrement not null, "store_id" integer, "language_code" varchar not null, "from_path" varchar not null, "to_path" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "url_rewrites" ("id" integer primary key autoincrement not null, "language_code" varchar not null, "request_path" varchar not null, "entity_type" varchar not null, "entity_id" integer not null, "store_id" integer);
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "warehouse_stocks" ("id" integer primary key autoincrement not null, "warehouse_id" integer not null, "product_id" integer not null, "qty" numeric not null default ('0'), "reserved_qty" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("warehouse_id") references warehouses("id") on delete cascade on update no action, foreign key("product_id") references products("id") on delete cascade on update no action);
CREATE TABLE "warehouse_translations" ("id" integer primary key autoincrement not null, "warehouse_id" integer not null, "language_code" varchar not null, "name" varchar not null, "description" text, foreign key("warehouse_id") references "warehouses"("id") on delete cascade);
CREATE TABLE "warehouses" ("id" integer primary key autoincrement not null, "name" varchar not null, "code" varchar not null, "is_default" tinyint(1) not null default '0', "is_enabled" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "email" varchar, "phone" varchar, "website" varchar, "address" varchar, "address_line2" varchar, "city" varchar, "state" varchar, "postcode" varchar, "country" varchar, "fax" varchar, "latitude" numeric, "longitude" numeric, "logo_path" varchar);
CREATE TABLE "webauthn_credentials" ("id" integer primary key autoincrement not null, "authenticatable_type" varchar not null, "authenticatable_id" integer not null, "credential_id" varchar not null, "public_key" text not null, "sign_count" integer not null default '0', "name" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "webhook_deliveries" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "webhook_endpoint_id" integer not null, "commerce_event_id" integer, "event" varchar not null, "payload" text not null, "status" varchar not null, "attempts" integer not null default '0', "available_at" datetime not null, "sent_at" datetime, "response_code" integer, "response_body" varchar, "last_error" varchar, "created_at" datetime, "updated_at" datetime, foreign key("webhook_endpoint_id") references "webhook_endpoints"("id") on delete cascade);
CREATE TABLE "webhook_endpoints" ("id" integer primary key autoincrement not null, "store_id" integer, "name" varchar not null, "url" varchar not null, "secret" varchar, "event_pattern" varchar not null default '*', "is_enabled" tinyint(1) not null default '1', "last_status" varchar, "last_error" varchar, "last_sent_at" datetime, "created_at" datetime, "updated_at" datetime, "events" text, "secret_ciphertext" text, "secret_prefix" varchar, "consecutive_failures" integer not null default '0', "disabled_at" datetime);
CREATE TABLE "webservice_keys" ("id" integer primary key autoincrement not null, "store_id" integer, "name" varchar not null, "key_prefix" varchar not null, "key_hash" varchar not null, "scopes" text not null, "allowed_ips" text, "is_enabled" tinyint(1) not null default '1', "expires_at" datetime, "last_used_at" datetime, "last_ip" varchar, "created_by" integer, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "wishlist_shares" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "token" varchar not null, "is_enabled" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete cascade);
CREATE TABLE "wishlists" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "product_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete cascade);
CREATE INDEX "admin_impersonations_admin_id_index" on "admin_impersonations" ("admin_id");
CREATE INDEX "admin_impersonations_customer_id_index" on "admin_impersonations" ("customer_id");
CREATE UNIQUE INDEX "admin_notif_read_unique" on "admin_notification_reads" ("admin_notification_id", "admin_id");
CREATE INDEX "admin_notif_subject_idx" on "admin_notifications" ("subject_type", "subject_id", "type");
CREATE INDEX "admin_notifications_store_id_index" on "admin_notifications" ("store_id");
CREATE INDEX "admin_notifications_type_index" on "admin_notifications" ("type");
CREATE UNIQUE INDEX "admins_email_unique" on "admins" ("email");
CREATE INDEX "ai_assistant_chats_admin_id_index" on "ai_assistant_chats" ("admin_id");
CREATE INDEX "ai_assistant_logs_admin_id_index" on "ai_assistant_logs" ("admin_id");
